begin;
set local statement_timeout='10s';
select set_config('test.owner',(select id::text from public.profiles where role='owner' and status='active' limit 1),true);
select set_config('test.row',gen_random_uuid()::text,true);
select set_config('test.source',gen_random_uuid()::text,true);
select set_config('test.recovery',gen_random_uuid()::text,true);
insert into public.platform_records(id,entity,owner_id,data) values(current_setting('test.row')::uuid,'OwnerAuditFixture',current_setting('test.owner')::uuid,'{"value":"original"}');
insert into private.owner_record_backups(id,created_by,status,completed_at) values(current_setting('test.source')::uuid,current_setting('test.owner')::uuid,'ready',now()),(current_setting('test.recovery')::uuid,current_setting('test.owner')::uuid,'ready',now());
insert into private.owner_record_backup_rows(backup_id,record_id,entity,owner_id,data,created_at) select current_setting('test.source')::uuid,id,entity,owner_id,data,created_at from public.platform_records where id=current_setting('test.row')::uuid;
update public.platform_records set data='{"value":"changed"}' where id=current_setting('test.row')::uuid;
insert into private.owner_record_backup_rows(backup_id,record_id,entity,owner_id,data,created_at) select current_setting('test.recovery')::uuid,id,entity,owner_id,data,created_at from public.platform_records where id=current_setting('test.row')::uuid;
select set_config('request.jwt.claim.sub',current_setting('test.owner'),true);
set local role authenticated;
do $$ declare r jsonb; repeated jsonb; b jsonb; begin
 b:=public.owner_maintenance('BACKUP','{}');
 if (b->>'record_count')::int<>50 or (b->>'complete')::boolean then raise exception 'Backup batch boundary failed'; end if;
 b:=public.owner_maintenance('BACKUP',jsonb_build_object('backup_id',b->>'backup_id'));
 if (b->>'record_count')::int<>100 then raise exception 'Backup continuation failed'; end if;
 r:=public.owner_maintenance('RESTORE',jsonb_build_object('backup_id',current_setting('test.source'),'recovery_backup_id',current_setting('test.recovery')));
 if (r->>'complete')::boolean is not true or (r->>'record_count')::int<>1 then raise exception 'Restore failed'; end if;
 if (select data->>'value' from public.platform_records where id=current_setting('test.row')::uuid)<>'original' then raise exception 'Restored content differs'; end if;
 repeated:=public.owner_maintenance('RESTORE',jsonb_build_object('backup_id',current_setting('test.source'),'recovery_backup_id',current_setting('test.recovery')));
 if repeated<>r then raise exception 'Restore retry not idempotent'; end if;
 r:=public.owner_maintenance('EXPORT','{"export_type":"full"}');
 if jsonb_array_length(r->'rows')<>200 or not (r->>'has_more')::boolean then raise exception 'Export boundary failed'; end if;
 r:=public.owner_maintenance('RESET_ONBOARDING','{}');
 if not (r->>'success')::boolean then raise exception 'Reset not saved'; end if;
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 begin perform public.owner_maintenance('BACKUP','{}'); raise exception 'Customer backup allowed'; exception when insufficient_privilege then null; end;
 if not public.runtime_status() ? 'maintenance_mode' then raise exception 'Public runtime projection missing'; end if;
end $$;
select 'PASS backup continuation, exact restore, repeat safety, 200-row export, onboarding persistence and owner isolation' checks;
rollback;
